# frozen_string_literal: true

require_relative 'project'

module Carton
  module Tools
    # RBS for a Project's imports, so a type checker like Steep knows what each
    # `import` returns. An exported constant names the Carton's own type,
    # which the Carton's RBS declares, and a keyword export is a record type.
    class Signatures
      HEADER = <<~RBS
        # Generated by `carton rbs` from the app's imports. Do not edit.
      RBS

      def initialize(project)
        @project = project
      end

      def to_s
        [HEADER, kernel, *constants].compact.join("\n")
      end

      private

      # One `Kernel#import` overload per literal path that means the same
      # Carton everywhere it is written. `import_relative` paths depend on the
      # calling file, so one that resolves differently in two files is left to
      # the untyped signature.
      def kernel
        overloads =
          SourceFile::IMPORTS.filter_map do |kind|
            types =
              edges_by_path(kind).filter_map do |path, cartons|
                next unless cartons.uniq.size == 1

                type = type_of(cartons.first)
                "(#{path.inspect} path) -> #{type}" unless type == 'untyped'
              end
            next if types.empty?

            lines =
              types.each_with_index.map do |type, index|
                if index.zero?
                  "  def #{kind}: #{type}"
                else
                  "#{' ' * (kind.size + 6)}| #{type}"
                end
              end
            [*lines, "#{' ' * (kind.size + 6)}| ..."].join("\n")
          end
        return if overloads.empty?

        ['module Kernel', '  private', *overloads, 'end', ''].join("\n")
      end

      def edges_by_path(kind)
        @project
          .edges
          .select { |edge| edge.carton && edge.call.kind == kind }
          .group_by { |edge| edge.call.path }
          .transform_values { |edges| edges.map(&:carton) }
          .sort
      end

      # `CONST = import ...` in any file, unless the Carton's own RBS already
      # declares that name: `Billing = import 'billing'` for `export Billing`.
      # A constant bound to two different Cartons is skipped.
      def constants
        bindings =
          @project
            .edges
            .select { |edge| edge.carton && edge.call.constant }
            .group_by { |edge| edge.call.constant }
            .transform_values { |edges| edges.map(&:carton).uniq }
            .select { |_, cartons| cartons.size == 1 }
        lines =
          bindings.sort.filter_map do |constant, (carton)|
            type = type_of(carton)
            next if type == "singleton(::#{constant})"

            alias_of(constant, carton, type) || "#{constant}: #{type}"
          end
        return if lines.empty?

        ['# Constants bound to imports', *lines, ''].join("\n")
      end

      def alias_of(constant, carton, type)
        target = type[/\Asingleton\((.+)\)\z/, 1] or return

        kind = definition_kind(carton, target.delete_prefix('::'))
        "#{kind} #{constant} = #{target}" if kind
      end

      def type_of(carton)
        exports = file(carton.entrypoint).exports
        return 'untyped' unless exports.size == 1

        export = exports.first
        return "singleton(::#{export.value})" if export.value
        return 'untyped' unless export.keys&.any?

        fields = export.keys.map { |key, type| "#{key}: #{type}" }
        "{ #{fields.join(', ')} }"
      end

      def file(path) = @project.files.fetch(path)

      def definition_kind(carton, name)
        carton.files.each do |path|
          kind = file(path).definitions[name]
          return kind if kind
        end
        nil
      end
    end
  end
end
